1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	const sorted = (cells: Cell[]): Cell[] =>
5	  [...cells].sort(([ax, ay], [bx, by]) => ax - bx || ay - by);
6	
7	const verticalBlinker: Cell[] = [
8	  [0, 0],
9	  [0, 1],
10	  [0, 2],
11	];
12	
13	const horizontalBlinker: Cell[] = [
14	  [-1, 1],
15	  [0, 1],
16	  [1, 1],
17	];
18	
19	const block: Cell[] = [
20	  [0, 0],
21	  [1, 0],
22	  [0, 1],
23	  [1, 1],
24	];
25	
26	describe("Game of Life - Next Generation", () => {
27	  it("should return an empty grid for a single live cell with no neighbors", () => {
28	    expect(nextGeneration([[0, 0]])).toEqual([]);
29	  });
30	  it("should return an empty grid for two adjacent cells that each have one neighbor", () => {
31	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
32	  });
33	  it("should keep a live cell with three live neighbors alive", () => {
34	    expect(nextGeneration([[0, 0], [1, 0], [2, 0], [1, 1]])).toContainEqual([
35	      1, 1,
36	    ]);
37	  });
38	  it("should kill a live cell with four live neighbors", () => {
39	    expect(
40	      nextGeneration([
41	        [1, 1],
42	        [0, 0],
43	        [0, 1],
44	        [0, 2],
45	        [1, 0],
46	      ]),
47	    ).not.toContainEqual([1, 1]);
48	  });
49	  it("should bring a dead cell with exactly three live neighbors to life", () => {
50	    expect(
51	      nextGeneration([
52	        [0, 0],
53	        [1, 0],
54	        [0, 1],
55	      ]),
56	    ).toContainEqual([1, 1]);
57	  });
58	  it("should turn a vertical blinker into a horizontal blinker", () => {
59	    expect(sorted(nextGeneration(verticalBlinker))).toEqual(
60	      sorted(horizontalBlinker),
61	    );
62	  });
63	  it("should turn a horizontal blinker back into a vertical blinker", () => {
64	    expect(sorted(nextGeneration(horizontalBlinker))).toEqual(
65	      sorted(verticalBlinker),
66	    );
67	  });
68	  it("should leave a block unchanged", () => {
69	    expect(sorted(nextGeneration(block))).toEqual(sorted(block));
70	  });
71	  it.todo("should compute the next generation for cells at negative coordinates");
72	});
73

1	export type Cell = [number, number];
2	
3	const NEIGHBOR_OFFSETS: Cell[] = [
4	  [-1, -1],
5	  [-1, 0],
6	  [-1, 1],
7	  [0, -1],
8	  [0, 1],
9	  [1, -1],
10	  [1, 0],
11	  [1, 1],
12	];
13	
14	const neighborsOf = ([x, y]: Cell): Cell[] =>
15	  NEIGHBOR_OFFSETS.map(([dx, dy]): Cell => [x + dx, y + dy]);
16	
17	const identityOf = ([x, y]: Cell): string => `${x},${y}`;
18	
19	const isLive = (cell: Cell, liveIdentities: Set<string>): boolean =>
20	  liveIdentities.has(identityOf(cell));
21	
22	const countLiveNeighbors = (cell: Cell, liveIdentities: Set<string>): number =>
23	  neighborsOf(cell).filter((neighbor) => isLive(neighbor, liveIdentities)).length;
24	
25	const withoutDuplicates = (cells: Cell[]): Cell[] => [
26	  ...new Map(cells.map((cell) => [identityOf(cell), cell])).values(),
27	];
28	
29	const candidatesForNextGeneration = (liveCells: Cell[]): Cell[] =>
30	  withoutDuplicates([...liveCells, ...liveCells.flatMap(neighborsOf)]);
31	
32	const SURVIVAL_NEIGHBOR_COUNTS = [2, 3];
33	const BIRTH_NEIGHBOR_COUNT = 3;
34	
35	const isAliveNextGeneration = (
36	  cell: Cell,
37	  liveIdentities: Set<string>,
38	): boolean => {
39	  const liveNeighbors = countLiveNeighbors(cell, liveIdentities);
40	  return isLive(cell, liveIdentities)
41	    ? SURVIVAL_NEIGHBOR_COUNTS.includes(liveNeighbors)
42	    : liveNeighbors === BIRTH_NEIGHBOR_COUNT;
43	};
44	
45	export const nextGeneration = (liveCells: Cell[]): Cell[] => {
46	  const liveIdentities = new Set(liveCells.map(identityOf));
47	  return candidatesForNextGeneration(liveCells).filter((cell) =>
48	    isAliveNextGeneration(cell, liveIdentities),
49	  );
50	};
